CREATE TABLE books (
	id INTEGER NOT NULL, 
	ol_work_key VARCHAR(64) NOT NULL, 
	title VARCHAR NOT NULL, 
	authors VARCHAR NOT NULL, 
	cover_id INTEGER, 
	cover_image_url VARCHAR(512), 
	spine_color VARCHAR(7), 
	year INTEGER, 
	description VARCHAR NOT NULL, 
	pages INTEGER, 
	subjects VARCHAR NOT NULL, 
	ol_rating FLOAT, 
	details_fetched_at DATETIME, 
	PRIMARY KEY (id)
);
INSERT INTO "books" VALUES(1,'/works/BC0000000001','Die Bibliothek am Meer','Mara Winter',NULL,NULL,NULL,2025,'Als Nora eine kleine Bibliothek an der Küste übernimmt, findet sie Briefe zwischen den Seiten. Eine Geschichte über Freundschaft, Neuanfänge und die Bücher, die uns begleiten.',320,'["Roman"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(2,'/works/BC0000000002','Zwischen den Sternen','Jonas Berg',NULL,NULL,NULL,2024,'Eine Forscherin empfängt ein Signal aus einer verlassenen Raumstation. Mit einer ungewöhnlichen Crew macht sie sich auf die Suche nach seinem Ursprung.',384,'["Science Fiction"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(3,'/works/BC0000000003','Ein Sommer in Lissabon','Clara Sommer',NULL,NULL,NULL,2023,'Drei Freunde treffen sich nach zehn Jahren wieder. In den Gassen von Lissabon entdecken sie, was sich verändert hat und was geblieben ist.',272,'["Roman"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(4,'/works/BC0000000004','Der Garten der Zeit','Emil Falk',NULL,NULL,NULL,2022,'Hinter einer unscheinbaren Tür liegt ein Garten, in dem jede Pflanze eine Erinnerung bewahrt. Doch einige Erinnerungen beginnen zu verschwinden.',296,'["Fantasy"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(5,'/works/BC0000000005','Kleine Wege, große Welten','Lea Neumann',NULL,NULL,NULL,2025,'Geschichten und Anregungen für Entdeckungen vor der eigenen Haustür: mit offenen Augen durch den Alltag und zu Fuß ins nächste Abenteuer.',224,'["Sachbuch"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(6,'/works/BC0000000006','Nachtzug nach Norden','Finn Hansen',NULL,NULL,NULL,2024,'Ein Nachtzug bleibt im Schnee stehen. Als ein Passagier verschwindet, muss eine pensionierte Ermittlerin herausfinden, wem sie vertrauen kann.',352,'["Krimi"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(7,'/works/BC0000000007','Das Haus der leisen Stimmen','Sophie Adler',NULL,NULL,NULL,2021,'Nach dem Tod ihrer Großmutter kehrt eine junge Musikerin in ihr Heimatdorf zurück und beginnt, die Geschichte ihrer Familie neu zu hören.',304,'["Roman"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(8,'/works/BC0000000008','Kaffee mit dem Morgen','Paul Richter',NULL,NULL,NULL,2025,'Zwölf kurze Geschichten über zufällige Begegnungen in einem Café. Warmherzig, humorvoll und voller kleiner Überraschungen.',192,'["Erzählungen"]',NULL,'2026-09-01 12:00:00.123456');
INSERT INTO "books" VALUES(9,'/works/OL45883W','Middlemarch','George Eliot',12345,NULL,'#a1b2c3',1871,'A study of provincial life.',880,'["Fiction", "England -- Fiction", "Domestic fiction"]',4.1,'2026-07-23 12:00:00.123456');
