CREATE TABLE next_up_ballots (
	id INTEGER NOT NULL, 
	vote_id INTEGER NOT NULL, 
	nomination_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
